function JournalHeaderSearch({ account, markups, reviews, onNavigate }) {
  const [query, setQuery] = useState("");
  const [focused, setFocused] = useState(false);
  const inputRef = useRef(null);
  useEffect(() => {
    const shortcut = (event) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); inputRef.current?.focus(); }
      if (event.key === "Escape") { setQuery(""); setFocused(false); inputRef.current?.blur(); }
    };
    window.addEventListener("keydown", shortcut);
    return () => window.removeEventListener("keydown", shortcut);
  }, []);
  const records = [
    ...(account.trades || []).map((trade) => ({id:`trade-${trade.id}`,page:"tradelog",title:`${trade.asset || "Trade"} · ${trade.date || ""}`,kind:"Trade",text:[trade.context,trade.notes,trade.entryType,trade.strategy].filter(Boolean).join(" · ")})),
    ...markups.map((markup) => ({id:`markup-${markup.id}`,page:"markups",title:`${markup.instrument || "Markup"} · ${markup.date || ""}`,kind:"Markup",text:[markup.bias,markup.notes,markup.structure].filter(Boolean).join(" · ")})),
    ...reviews.map((review) => ({id:`review-${review.id}`,page:"reviews",title:`Review · ${review.date || ""}`,kind:"Review",text:[review.notes,review.lesson,review.summary].filter(Boolean).join(" · ")}))
  ];
  const matches = query.trim() ? records.filter((record) => `${record.title} ${record.text}`.toLowerCase().includes(query.trim().toLowerCase())) : [];
  return <div className="tj-header-search" onBlur={(event) => { if (!event.currentTarget.contains(event.relatedTarget)) setFocused(false); }}>
    <Search size={14} aria-hidden="true"/><input ref={inputRef} aria-label="Search trades, markups, notes" placeholder="Search trades, markups, notes..." value={query} onFocus={() => setFocused(true)} onChange={(event) => setQuery(event.target.value)}/><kbd>⌘K</kbd>
    {focused && query.trim() && <div className="tj-header-search-results" role="region" aria-label="Journal search results"><small>{matches.length} matching records in this journal</small>{matches.slice(0,8).map((record) => <button type="button" key={record.id} onClick={() => {setQuery("");setFocused(false);onNavigate(record.page);}}><span>{record.kind}</span><strong>{record.title}</strong>{record.text && <p>{record.text}</p>}</button>)}{!matches.length && <p>No matching trades, markups, or notes.</p>}</div>}
  </div>;
}
const JOURNAL_PATHS = Object.freeze(Object.fromEntries(NAV.map(({ id }) => [id, `/${id === NAV[2].id ? `${id.slice(0, 5)}-${id.slice(5)}` : id === NAV[3].id ? id.slice(0, -1) : id}`])));
const LEGACY_JOURNAL_PATH = `/${['j', 'o', 'u', 'r', 'n', 'a', 'l'].join('')}`;
