  const hasCompletedAccountResult = multiBalance && (form.balanceResults || []).some((result) => result.grossPnl !== "" && result.grossPnl != null);
  const hasRecordedExit = form.calculationMethod === "pips" ? form.exitPips !== "" && form.exitPips != null : form.calculationMethod === "price" ? form.exitPrice !== "" && form.exitPrice != null : false;
  const isRunning = multiBalance ? !hasCompletedAccountResult : (form.grossPnl === "" || form.grossPnl == null) && !hasRecordedExit;
  const liveNetPnl = (Number(form.grossPnl) || 0) - (Number(form.commission) || 0) - (Number(form.swap) || 0);
  const isLossResult = liveNetPnl < 0;
