      return { ...result, entryPrice: result.entryPrice ?? form.entryPrice, exitPrice: result.exitPrice ?? form.exitPrice, closeDate: result.closeDate ?? form.closeDate, closeTime: result.closeTime ?? form.closeTime, grossPnl: resultIsRunning ? 0 : Number(result.grossPnl), commission: Number(result.commission) || 0, swap: Number(result.swap) || 0, netPnl: (Number(result.grossPnl) || 0) - (Number(result.commission) || 0) - (Number(result.swap) || 0), status: resultIsRunning ? "open" : "closed" };
