      if (localProfileResult.error) return showError(localProfileResult.error || 'Could not inspect the device Case Study Library. Cloud Sync remains enabled.');
      const profileCopy = prepareProfileLibraryDeviceCopy({ cloudLibrary:profileResult.data, localLibrary:localProfileResult.data, visibleLibrary:profileCaseStudyWorkspace });
      if (profileCopy.error) return showError(profileCopy.error);
      const data = { accounts, typeTags, mistakeTags, confluenceSessions, customInstruments, markups, reviews, periodReviews, profileCaseStudyLibrary:profileCopy.data, challengeProgress:challengeResult.data, balancesReady: balanceStorageReady, financeReady: true };
      const saved = await localJournal.importLocalJournal(user.id, { version: 1, data });
